const inputJson = $input.item.json || {};
const body = inputJson.body || inputJson;
const issue = body.issue || inputJson.issue || {};
const issueId = issue.id || body.issue_id || inputJson.issue_id || "";
const images = issue.images || body.images || [];
const mapsUrl = issue.maps_link || (issue.lat && issue.lng ? `https://www.google.com/maps?q=${issue.lat},${issue.lng}` : "https://maps.google.com");
const chatId = body.chat_id || inputJson.chat_id || "404755091";

const formattedPriority = typeof issue.priority_score === 'number' ? (issue.priority_score >= 1 ? Math.round(issue.priority_score) : issue.priority_score.toFixed(2)) : (issue.priority_score || '0');

let formattedMessage = "🚨 *CIVICFIX MUNICIPAL DISPATCH*\n\n" +
  "📌 *Issue*: " + (issue.title || "Infrastructure Defect") + "\n" +
  "🆔 *Issue ID*: `" + issueId + "`\n" +
  "📄 *Description*: " + (issue.description || "No detailed description provided.") + "\n" +
  "📍 *Location*: " + (issue.address || "Addis Ababa") + "\n" +
  "🏙️ *Sub-City*: " + (issue.subcity || "Bole") + "\n" +
  "👷 *Assigned Unit*: " + (issue.assigned_unit || "Field Unit 1") + "\n" +
  "⚡ *Priority Score*: " + formattedPriority + "\n" +
  "📝 *Officer Notes*: " + (body.dispatch_notes || "Immediate priority repair requested.") + "\n\n";

if (images && images.length > 0) {
  formattedMessage += "🖼️ [View Attached Issue Photo](" + images[0] + ")\n\n";
}

formattedMessage += "👇 *Use the interactive buttons below on your phone:*";

const inlineKeyboardObj = {
  inline_keyboard: [
    [
      { "text": "🗺️ MAPS Open Navigation", "url": mapsUrl }
    ],
    [
      { "text": "📸 Submit Repair Proof", "callback_data": `resolve:${issueId}` },
      { "text": "💵 Log Cost (4,500 ETB)", "callback_data": `cost:${issueId}` }
    ],
    [
      { "text": "🌐 LANG Amharic / English", "callback_data": `lang:${issueId}` }
    ]
  ]
};

return {
  json: {
    issue_id: issueId,
    chat_id: chatId,
    formatted_message: formattedMessage,
    inline_keyboard: inlineKeyboardObj,
    maps_link: mapsUrl,
    raw_payload: body
  }
};

const inputJson = $input.item.json || {};
const data = inputJson.body || inputJson;
const callbackQuery = data.callback_query;
const message = data.message;

let action = "ignore";
let issueId = "";
let callbackQueryId = "";
let chatId = "404755091";
let photoFileId = "";

if (callbackQuery) {
  const callbackData = callbackQuery.data || "";
  callbackQueryId = String(callbackQuery.id || "");
  chatId = String(callbackQuery.message?.chat?.id || callbackQuery.from?.id || "404755091");

  if (callbackData.startsWith("resolve:")) {
    action = "resolve";
    issueId = callbackData.replace("resolve:", "");
  } else if (callbackData.startsWith("cost:")) {
    action = "cost";
    issueId = callbackData.replace("cost:", "");
  } else if (callbackData.startsWith("lang:")) {
    action = "lang";
    issueId = callbackData.replace("lang:", "");
  }
} else if (message) {
  chatId = String(message.chat?.id || "404755091");
  if (message.photo && message.photo.length > 0) {
    action = "photo_proof";
    const lastPhoto = message.photo[message.photo.length - 1];
    photoFileId = lastPhoto.file_id;

    const replyText = message.reply_to_message?.text || message.caption || "";
    const match = replyText.match(/`([a-f0-9\-]{8,})`/) || replyText.match(/Issue\s*#?([a-f0-9\-]{8,})/i);
    if (match) issueId = match[1];
  }
}

return {
  json: {
    skip: action === "ignore",
    action,
    issue_id: issueId,
    callback_query_id: callbackQueryId,
    chat_id: chatId,
    photo_file_id: photoFileId
  }
};

